package in.foodcart.config;
import in.foodcart.data.*;import in.foodcart.domain.OrderStatus;import in.foodcart.domain.VendorStatus;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import java.math.BigDecimal;
@Configuration public class DemoData {@Bean CommandLineRunner moreDemoData(VendorRepository vendors,MenuCategoryRepository categories,MenuItemRepository items,OrderRepository orders){return a->{VendorEntity r=vendors.findBySlug("raju-momos").orElse(null);if(r!=null&&orders.findByVendorIdOrderByCreatedAtDesc(r.id).isEmpty()){String[] names={"Veg Momos","Cold Coffee","Egg Roll"};int[] prices={80,70,70};for(int n=0;n<3;n++){OrderEntity o=new OrderEntity();o.vendorId=r.id;o.customerId="demo-customer";o.customerMobile="9999999999";o.orderNumber=1042-n;o.type=n==1?"DINE_IN":"PICKUP";o.status=n==0?OrderStatus.PLACED:n==1?OrderStatus.PREPARING:OrderStatus.COMPLETED;o.total=o.subtotal=BigDecimal.valueOf(prices[n]);OrderEntity.Item line=new OrderEntity.Item();line.name=names[n];line.price=BigDecimal.valueOf(prices[n]);line.lineTotal=line.price;line.quantity=1;o.items.add(line);orders.save(o);}}if(vendors.findBySlug("sharma-chaat").isEmpty()){VendorEntity v=new VendorEntity();v.name="Sharma Chaat";v.slug="sharma-chaat";v.mobile="8888888888";v.description="Tangy, crisp chaat made fresh at the counter";v.address="Market Lane, Sector 18";v.status=VendorStatus.OPEN;v=vendors.save(v);MenuCategoryEntity c=new MenuCategoryEntity();c.vendorId=v.id;c.name="Chaat";categories.save(c);for(Object[] x:new Object[][]{{"Papdi Chaat","90"},{"Aloo Tikki","70"},{"Dahi Bhalla","80"}}){MenuItemEntity i=new MenuItemEntity();i.vendorId=v.id;i.categoryId=c.id;i.name=(String)x[0];i.description="Made fresh with house chutneys";i.price=new BigDecimal((String)x[1]);items.save(i);}}};}}
